  ?dev rdfs:label ?dname .
}

PREFIX brick: <http://brickschema.org/schema/1.1/brick#>
SELECT ?p ?cls WHERE {
  ?p a ?cls .
  FILTER(str(?cls) LIKE "%Power%")
}

